import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"Manager-Led Media Package Offering Models, Public Guest Share Token & Task Seeding","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/03-campaign-package-delivery/manager-led-media-package-sharing/spec.md","filePath":"feature/modules/03-campaign-package-delivery/manager-led-media-package-sharing/spec.md"}'),n={name:"feature/modules/03-campaign-package-delivery/manager-led-media-package-sharing/spec.md"};function c(r,e,d,s,l,g){return t(),o("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="manager-led-media-package-offering-models-public-guest-share-token-task-seeding" tabindex="-1">Manager-Led Media Package Offering Models, Public Guest Share Token &amp; Task Seeding <a class="header-anchor" href="#manager-led-media-package-offering-models-public-guest-share-token-task-seeding" aria-label="Permalink to &quot;Manager-Led Media Package Offering Models, Public Guest Share Token &amp; Task Seeding&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>manager-led-media-package-sharing</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>03-campaign-package-delivery</code> — Media Package Sharing, Campaign Timeline &amp; Delivery Closure</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>guest-sharing-manager-led</code>, <code>offering-models</code>, <code>package-simplification</code>, <code>package-quantity-input</code>, <code>package-driven-campaign-tasks</code>, <code>media-workspace-ux</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/04-media-package-campaign/README.html">3.5 Media Package &amp; Media Campaign</a> (<code>3.5.1–3.5.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Streamline the commercial Media Package lifecycle from Agency template creation (<code>offering-models</code>, <code>package-simplification</code>, <code>package-quantity-input</code>), public token-gated <code>Guest</code> share links (<code>GET /api/v1/public/media-packages/{token}</code>), and <code>Manager</code>-led Workspace package planning (<code>WorkspacePackagePlanningController</code>) through <code>Client</code> negotiation/approval and deterministic Campaign deliverable Task generation (<code>package-driven-campaign-tasks</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code> or <code>Manager</code>, I want to configure structured Media Package deliverables (fixed bundle, flexible item quantities, or recurring monthly cadence), share read-only public preview links with prospective <code>Guest</code> leads, and automatically materialize Campaign Tasks once the <code>Client</code> approves the Workspace package.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Structured Offering Models &amp; Clean Quantity Editing (<code>offering-models</code>, <code>package-simplification</code>, <code>package-quantity-input</code>):</strong> Supports <code>FIXED_BUNDLE</code>, <code>CUSTOM_QUOTE</code>, and <code>RETAINER</code> package structures with typed deliverable line items (<code>taskType</code>, <code>platform</code>, <code>quantity &gt;= 1</code>, unit description). Numeric quantity inputs allow clean backspace/retype without <code>NaN</code> or sticky leading-zero bugs.</li><li><strong>Token-Gated Public <code>Guest</code> Sharing (<code>guest-sharing-manager-led</code>, <code>2026-11-06-manager-led-package-sharing.sql</code>):</strong> <code>MediaPackageShareController</code> issues revocable, optionally expiring share tokens (<code>GET /api/v1/public/media-packages/{token}</code>) exposing sanitized package deliverables and Agency branding to <code>Guest</code> viewers without leaking internal workspace notes or other clients.</li><li><strong>Manager-Led Workspace Planning &amp; Impact Preview (<code>WorkspacePackagePlanningController</code>):</strong> <code>PUT /api/v1/workspaces/{workspaceId}/media-package</code> and <code>POST /impact</code> compute exact deliverable deltas; <code>package_negotiation_events</code> logs every proposal, <code>Client</code> counter-note, and final approval (<code>POST /approve</code>).</li><li><strong>Deterministic Package -&gt; Campaign -&gt; Task Provisioning (<code>package-driven-campaign-tasks</code>):</strong> Deploying an approved package/campaign (<code>POST /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/deploy</code>) idempotently generates typed deliverable Tasks (<code>tasks</code> + MongoDB <code>TaskDocument</code>) matching exact line-item quantities.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>mediaPackage.{models,share,negotiation,quantities,impact}.*</code> in <code>src/i18n/locales/{vi,en}/mediaPackage.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/client/components/ServicePackageModal.tsx</code>, <code>pages/campaign/components/CampaignDeploymentPanel.tsx</code>, public package share page</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/MediaPackageScreen.tsx</code>, <code>src/screens/agency/AgencyMediaPackagesScreen.tsx</code>, <code>src/services/mediaPackageService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/media-package-templates &amp; POST /api/v1/agencies/{agencyId}/media-package-custom</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>MediaPackageController</code> -&gt; manages Agency package templates &amp; availability</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/public/media-packages/{token}</code></td><td style="text-align:left;">Public (<code>Guest</code>)</td><td style="text-align:left;"><code>MediaPackageShareController</code> -&gt; read-only sanitized public package view</td></tr><tr><td style="text-align:left;"><code>PUT /api/v1/workspaces/{workspaceId}/media-package &amp; POST /impact &amp; GET /history</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>WorkspacePackagePlanningController</code> &amp; <code>PackageNegotiationHistoryController</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/media-package/approve</code></td><td style="text-align:left;">Bearer (<code>Client, Owner, Manager</code>)</td><td style="text-align:left;"><code>MediaPackageController</code> -&gt; locks approved Workspace package snapshot</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Revoked or Expired Share Token:</strong> Returns <code>404/410</code> localized &#39;Link Unavailable&#39; page to <code>Guest</code> with zero Agency internal metadata.</li><li><strong>Retry Preparation / Deploy (<code>POST /preparation/retry</code>):</strong> Idempotent task-generation key prevents duplicate Tasks if network drops mid-deploy.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/04-media-package-campaign/README.html">3.5 Media Package &amp; Media Campaign</a> (<code>3.5.1–3.5.9</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/04-media-package-campaign.html">BA 04 Media Package &amp; Campaign</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=a(n,[["render",c]]);export{m as __pageData,u as default};
